"use client";

import {
  cloneElement,
  createContext,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type RefObject,
  use,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import type { Align, Side } from "../interaction/floating";
import { useDismiss, useFloating, usePresence } from "../interaction/use-floating";
import { cx } from "../utils/cx";
import { hasFinePointer } from "../utils/motion";

type HoverCardContextValue = {
  open: boolean;
  show: () => void;
  hide: () => void;
  triggerRef: RefObject<HTMLElement | null>;
  id: string;
  side: Side;
  align: Align;
};
const HoverCardContext = createContext<HoverCardContextValue | null>(null);

function useHoverCard(part: string): HoverCardContextValue {
  const ctx = use(HoverCardContext);
  if (!ctx) throw new Error(`<${part}> must be inside <HoverCard>`);
  return ctx;
}

export type HoverCardProps = {
  /** Hover time before it opens, ms. Keyboard focus opens it sooner. Default 450. */
  openDelay?: number;
  /** Grace time to move the pointer from the trigger into the card, ms. Default 180. */
  closeDelay?: number;
  side?: Side;
  align?: Align;
  children: ReactNode;
};

/**
 * A preview card for a link or a name: it opens on hover (fine pointers) or keyboard focus, stays open while the pointer
 * is on the trigger or the card, and closes on Escape. For essential content use `Popover`; the card is a convenience.
 */
export function HoverCard({
  openDelay = 450,
  closeDelay = 180,
  side = "bottom",
  align = "start",
  children,
}: HoverCardProps) {
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const triggerRef = useRef<HTMLElement>(null);
  const id = useId();
  const show = useCallback(() => {
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setOpen(true), openDelay);
  }, [openDelay]);
  const hide = useCallback(() => {
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setOpen(false), closeDelay);
  }, [closeDelay]);
  useEffect(() => () => clearTimeout(timer.current), []);
  return <HoverCardContext value={{ open, show, hide, triggerRef, id, side, align }}>{children}</HoverCardContext>;
}

type Handler = ((e: never) => void) | undefined;

/** The element that opens the card (a link, an avatar, a name). It must accept a ref and pointer and focus handlers. */
export function HoverCardTrigger({ children }: { children: ReactElement<Record<string, unknown>> }) {
  const { open, show, hide, triggerRef, id } = useHoverCard("HoverCardTrigger");
  const own = children.props;
  const chain = (name: string, fn: () => void) => (e: never) => {
    (own[name] as Handler)?.(e);
    fn();
  };
  return cloneElement(children, {
    ref: triggerRef,
    "aria-describedby": open ? id : (own["aria-describedby"] as string | undefined),
    onPointerEnter: chain("onPointerEnter", () => hasFinePointer() && show()),
    onPointerLeave: chain("onPointerLeave", hide),
    onFocus: (e: { currentTarget: Element }) => {
      (own.onFocus as Handler)?.(e as never);
      if (e.currentTarget.matches(":focus-visible")) show();
    },
    onBlur: chain("onBlur", hide),
  });
}

export function HoverCardContent({ className, children, ...rest }: HTMLAttributes<HTMLDivElement>) {
  const { open, show, hide, triggerRef, id, side, align } = useHoverCard("HoverCardContent");
  const ref = useRef<HTMLDivElement>(null);
  const { present, state } = usePresence(open);
  useFloating(present, triggerRef, ref, { side, align, offset: 8 });
  const close = useCallback(() => hide(), [hide]);
  useDismiss(open, triggerRef, ref, close);
  if (!present) return null;
  return (
    <div
      {...rest}
      ref={ref}
      id={id}
      popover="manual"
      role="group"
      data-state={state}
      inert={state === "closed" || undefined}
      className={cx("hm-floating hm-popover hm-hover-card", className)}
      onPointerEnter={show}
      onPointerLeave={hide}
      onFocus={show}
      onBlur={hide}
    >
      {children}
    </div>
  );
}
